// Corndogs' own CSIL-RPC transport carrier: hand-written, NOT generated by csilgen.
// Reuses the generated CsilCbor codec for the envelope; owns only framing + the
// connection. Safe to edit — unlike the files above, this one is not regenerated.

package csilgen.generated;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.util.List;

import csilgen.generated.CsilCbor.CborEntry;
import csilgen.generated.CsilCbor.CborMap;
import csilgen.generated.CsilCbor.CborTag;
import csilgen.generated.CsilCbor.CborText;
import csilgen.generated.CsilCbor.CborUint;
import csilgen.generated.CsilCbor.CborBytes;
import csilgen.generated.CsilCbor.CborValue;

/**
 * Corndogs' own, ready-to-use CSIL-RPC carrier: a persistent TCP connection framed
 * with the canonical 4-byte big-endian length prefix (the CSIL StreamCarrier). You
 * do not need to write a carrier or read csilgen docs — point this at a corndogs
 * server's TCP address and hand it to the generated client:
 *
 * <pre>{@code
 * TcpTransport tr = TcpTransport.connect("localhost:5080");
 * tr.startHeartbeat(15_000);                 // keep the connection alive (background)
 * CorndogsClient client = new CorndogsClient(tr);
 * SubmitTaskResponse resp = client.submitTask(new SubmitTaskRequest(
 *     "emails", "submitted", "sending", -1, new byte[0], 0));
 * }</pre>
 *
 * <p>Synchronous, one call in flight at a time: every {@link #call} is serialized
 * under a lock (matching the sync {@link Transport} the generated client expects).
 * The connection is dialed lazily on first use and re-dialed on failure. This
 * carrier owns only the envelope + framing + connection; the generated client and
 * {@link CsilCbor} own (de)serialization. Thread-safe.
 */
public final class TcpTransport implements Transport, AutoCloseable {
    private static final long TAG_ENCODED_CBOR = 24; // RFC 8949 §3.4.5.1 — embedded encoded CBOR data item
    private static final String CONTROL_SERVICE = "CorndogsService";
    private static final String OP_PING = "$ping"; // control-plane heartbeat op (never collides with app ops)
    private static final int MAX_FRAME = 256 << 20; // frame size guard
    private static final int DEFAULT_CONNECT_TIMEOUT_MILLIS = 5_000;
    private static final long DEFAULT_HEARTBEAT_INTERVAL_MILLIS = 15_000;

    private final String host;
    private final int port;
    private final int connectTimeoutMillis;

    private final Object lock = new Object(); // guards socket/in/out/nextId/closed/heartbeatThread
    private Socket socket;
    private DataInputStream in;
    private DataOutputStream out;
    private long nextId = 0;
    private boolean closed = false;

    private Thread heartbeatThread;
    private volatile boolean heartbeatStop;

    public TcpTransport(String addr) {
        this(addr, DEFAULT_CONNECT_TIMEOUT_MILLIS);
    }

    public TcpTransport(String addr, int connectTimeoutMillis) {
        int idx = addr.lastIndexOf(':');
        if (idx <= 0 || idx == addr.length() - 1) {
            throw new IllegalArgumentException("corndogs: address must be host:port, got " + addr);
        }
        this.host = addr.substring(0, idx);
        this.port = Integer.parseInt(addr.substring(idx + 1));
        this.connectTimeoutMillis = connectTimeoutMillis;
    }

    /** Convenience: a ready {@code TcpTransport} for {@code addr} (host:port). */
    public static TcpTransport connect(String addr) {
        return new TcpTransport(addr);
    }

    private void ensureConnected() throws IOException {
        if (socket != null && !socket.isClosed()) {
            return;
        }
        Socket s = new Socket();
        s.connect(new InetSocketAddress(host, port), connectTimeoutMillis);
        s.setTcpNoDelay(true);
        socket = s;
        in = new DataInputStream(s.getInputStream());
        out = new DataOutputStream(s.getOutputStream());
    }

    private void reset() {
        if (socket != null) {
            try {
                socket.close();
            } catch (IOException ignored) {
                // best-effort close; the connection is being torn down anyway
            }
        }
        socket = null;
        in = null;
        out = null;
    }

    @Override
    public byte[] call(String service, String op, byte[] req) throws ClientException {
        synchronized (lock) {
            if (closed) {
                throw new ClientException("corndogs: transport closed");
            }
            try {
                ensureConnected();
                long id = ++nextId;
                byte[] payload = req == null ? new byte[0] : req;
                CborValue envelope = new CborMap(List.of(
                    new CborEntry(new CborText("v"), new CborUint(1)),
                    new CborEntry(new CborText("service"), new CborText(service)),
                    new CborEntry(new CborText("op"), new CborText(op)),
                    new CborEntry(new CborText("id"), new CborUint(id)),
                    new CborEntry(new CborText("payload"), new CborTag(TAG_ENCODED_CBOR, new CborBytes(payload)))
                ));
                writeFrame(CsilCbor.encode(envelope));
                byte[] frame = readFrame();
                if (frame == null) {
                    reset();
                    throw new ClientException("corndogs: connection closed");
                }
                return parseResponse(frame);
            } catch (IOException e) {
                reset();
                throw new ClientException("corndogs: " + service + "/" + op + ": " + e.getMessage(), e);
            }
        }
    }

    private void writeFrame(byte[] payload) throws IOException {
        if (payload.length > MAX_FRAME) {
            throw new IOException("corndogs: frame too large (" + payload.length + ")");
        }
        out.writeInt(payload.length); // DataOutputStream.writeInt is 4-byte big-endian
        out.write(payload);
        out.flush();
    }

    /** Reads one frame, or returns {@code null} if the peer closed the connection cleanly. */
    private byte[] readFrame() throws IOException {
        int len;
        try {
            len = in.readInt(); // 4-byte big-endian length prefix
        } catch (EOFException e) {
            return null;
        }
        if (len < 0 || len > MAX_FRAME) {
            throw new IOException("corndogs: frame too large (" + len + ")");
        }
        byte[] buf = new byte[len];
        in.readFully(buf);
        return buf;
    }

    /**
     * Decodes a response envelope into the inner payload bytes. A non-zero transport
     * status, or a "ServiceError" variant, becomes a thrown {@link ClientException}.
     */
    private static byte[] parseResponse(byte[] frame) {
        CborValue val;
        try {
            val = CsilCbor.decode(frame);
        } catch (RuntimeException e) {
            throw new ClientException("corndogs: decode response envelope: " + e.getMessage(), e);
        }
        CborValue statusV = CsilCbor.mapGet(val, "status");
        if (statusV != null) {
            long status = CsilCbor.asI64(statusV);
            if (status != 0) {
                String msg = "";
                CborValue errV = CsilCbor.mapGet(val, "error");
                if (errV != null) {
                    msg = CsilCbor.asText(errV);
                }
                throw new ClientException("corndogs: transport status " + status + ": " + msg);
            }
        }
        CborValue payloadV = CsilCbor.mapGet(val, "payload");
        if (payloadV == null) {
            return new byte[0]; // control replies (e.g. $pong) may carry no payload
        }
        if (payloadV instanceof CborTag tag) {
            payloadV = tag.inner();
        }
        byte[] inner = CsilCbor.asBytes(payloadV);
        CborValue variantV = CsilCbor.mapGet(val, "variant");
        if (variantV != null && "ServiceError".equals(CsilCbor.asText(variantV))) {
            ServiceError se = CsilCbor.decodeServiceError(inner);
            throw new ClientException("corndogs: service error " + se.code() + ": " + se.message());
        }
        return inner;
    }

    // --- heartbeat -------------------------------------------------------------

    /** Sends one control-plane heartbeat; throws {@link ClientException} if the server is unreachable. */
    public void ping() {
        call(CONTROL_SERVICE, OP_PING, new byte[0]);
    }

    /**
     * SYNCHRONOUS heartbeat start: blocks, pinging every {@code intervalMillis}
     * (default 15s if {@code <= 0}), until the current thread is interrupted or a
     * ping fails (throws {@link ClientException}). Run it on a thread you own, or
     * use {@link #startHeartbeat(long)} for the background form.
     */
    public void runHeartbeat(long intervalMillis) {
        long interval = intervalMillis > 0 ? intervalMillis : DEFAULT_HEARTBEAT_INTERVAL_MILLIS;
        try {
            while (!Thread.currentThread().isInterrupted()) {
                Thread.sleep(interval);
                ping();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    /**
     * ASYNCHRONOUS heartbeat start: runs the heartbeat on a background daemon
     * thread and returns a stop handle ({@link AutoCloseable#close} stops it; also
     * usable as a bare {@link Runnable} via a method reference). Only one
     * background heartbeat runs at a time; a second call returns a handle to the
     * existing one. Ended automatically by {@link #close()}.
     */
    public AutoCloseable startHeartbeat(long intervalMillis) {
        synchronized (lock) {
            if (heartbeatThread != null && heartbeatThread.isAlive()) {
                Thread existing = heartbeatThread;
                return () -> stopHeartbeatThread(existing);
            }
            heartbeatStop = false;
            long interval = intervalMillis > 0 ? intervalMillis : DEFAULT_HEARTBEAT_INTERVAL_MILLIS;
            Thread t = new Thread(() -> {
                while (!heartbeatStop) {
                    try {
                        Thread.sleep(interval);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                    if (heartbeatStop) {
                        return;
                    }
                    try {
                        ping();
                    } catch (RuntimeException e) {
                        return; // dead server / closed transport ends the heartbeat
                    }
                }
            }, "corndogs-heartbeat");
            t.setDaemon(true);
            heartbeatThread = t;
            t.start();
            return () -> stopHeartbeatThread(t);
        }
    }

    private void stopHeartbeatThread(Thread t) {
        synchronized (lock) {
            if (heartbeatThread == t) {
                heartbeatThread = null;
            }
        }
        heartbeatStop = true;
        t.interrupt();
    }

    /** Shuts the transport down: stops any heartbeat and closes the connection. Idempotent. */
    @Override
    public void close() {
        Thread hb;
        synchronized (lock) {
            closed = true;
            hb = heartbeatThread;
            heartbeatThread = null;
            reset();
        }
        if (hb != null) {
            heartbeatStop = true;
            hb.interrupt();
        }
    }
}
